#!/usr/bin/env python3
"""Deterministic control-flow check for the CVE-2019-20811 fix.

Asserts, for both rx_queue_add_kobject and netdev_queue_add_kobject in a
net/core/net-sysfs.c file:

  1. exactly one dev_hold(queue->dev) exists in the function body;
  2. it is reached after a successful kobject_init_and_add (i.e. after the
     kobject_init_and_add call);
  3. it precedes every kobject_put(kobj) in the function (the sysfs_create_group
     failure path), so the release callback's dev_put(queue->dev) is balanced;
  4. it no longer sits after kobject_uevent (the pre-fix vulnerable placement).

Exit 0 when all assertions hold, 1 otherwise.
"""
import sys


def extract_function(lines, signature_fragment):
    start = None
    for i, line in enumerate(lines):
        if signature_fragment in line:
            start = i
            break
    if start is None:
        return None
    # function body ends at the first line that is exactly "}" at column 0
    for j in range(start + 1, len(lines)):
        if lines[j].rstrip("\n") == "}":
            return lines[start:j + 1]
    return None


def check(path, signature, label):
    lines = open(path, "r", encoding="utf-8", errors="replace").read().splitlines()
    body = extract_function(lines, signature)
    if body is None:
        return [f"{label}: function not found"]
    errors = []

    def first_index(token):
        for i, line in enumerate(body):
            if token in line:
                return i
        return None

    holds = [i for i, line in enumerate(body) if "dev_hold(queue->dev)" in line]
    if len(holds) != 1:
        errors.append(f"{label}: expected exactly 1 dev_hold(queue->dev), found {len(holds)}")
        return errors
    hold = holds[0]

    init = first_index("kobject_init_and_add")
    put = first_index("kobject_put(kobj)")
    uevent = first_index("kobject_uevent")

    if init is None:
        errors.append(f"{label}: kobject_init_and_add not found")
    elif not hold > init:
        errors.append(f"{label}: dev_hold (line {hold}) is not after kobject_init_and_add (line {init})")
    if put is None:
        errors.append(f"{label}: kobject_put(kobj) not found")
    elif not hold < put:
        errors.append(f"{label}: dev_hold (line {hold}) is not before kobject_put (line {put})")
    if uevent is not None and hold > uevent:
        errors.append(f"{label}: dev_hold (line {hold}) still after kobject_uevent (line {uevent})")
    return errors


def main():
    path = sys.argv[1] if len(sys.argv) > 1 else "net/core/net-sysfs.c"
    problems = []
    problems += check(path, "static int rx_queue_add_kobject", "rx_queue_add_kobject")
    problems += check(path, "static int netdev_queue_add_kobject", "netdev_queue_add_kobject")
    if problems:
        for p in problems:
            print("FAIL:", p)
        return 1
    print("OK: dev_hold-before-release invariant holds in both queue add paths")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

